#include <algorithm>
#include <cassert>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>
using namespace std;
// 비어 있지 않은 연속 구간의 최대 합. 빈 배열은 해가 없습니다.
long long maxSum(const vector<int>&v){
 if(v.empty())throw invalid_argument("empty");
 long long ending=v[0],best=ending;
 for(size_t i=1;i<v.size();++i){ending=max(static_cast<long long>(v[i]),ending+v[i]);best=max(best,ending);}
 return best;
}
long long maxSumReference(const vector<int>&v){
 long long best=numeric_limits<long long>::min();
 for(size_t i=0;i<v.size();++i){long long sum=0;for(size_t j=i;j<v.size();++j){sum+=v[j];best=max(best,sum);}}
 return best;
}
vector<string> strings(const string&alphabet,int maximum){
 vector<string>all(1,""),level(1,"");for(int n=1;n<=maximum;++n){vector<string>next;for(const string&s:level)for(char c:alphabet)next.push_back(s+c);all.insert(all.end(),next.begin(),next.end());level=next;}return all;
}
int main(){size_t cases=0;for(const string&s:strings("012",8)){vector<int>v;for(char c:s)v.push_back(c-'1');if(!v.empty()){assert(maxSum(v)==maxSumReference(v));++cases;}}bool rejected=false;try{maxSum({});}catch(const invalid_argument&){rejected=true;}assert(rejected);assert(maxSum(vector<int>(100000,1000000000))==100000000000000LL);assert(maxSum(vector<int>(100000,-1000000000))==-1000000000LL);cout<<cases<<" cases\n";}
